#include <vpi_user.h>
static PLI_INT32 write_net(PLI_BYTE8 *unused) {
 (void)unused;
 vpiHandle call=vpi_handle(vpiSysTfCall,0),args=vpi_iterate(vpiArgument,call);
 vpiHandle net=vpi_scan(args),mode=vpi_scan(args);
 s_vpi_value flag={0}; flag.format=vpiIntVal; vpi_get_value(mode,&flag);
 while(vpi_scan(args)){}
 s_vpi_value value={0};value.format=vpiScalarVal;value.value.scalar=vpi1;
 vpi_put_value(net,&value,0,flag.value.integer);
 PLI_INT32 error=vpi_chk_error(0);
 value.format=vpiScalarVal;vpi_get_value(net,&value);
 vpi_printf("write %d value=%d error=%d\n",flag.value.integer,value.value.scalar,error);
 return 0;
}
static void startup(void) {
 s_vpi_systf_data data={0};data.type=vpiSysTask;data.tfname="$net_write";data.calltf=write_net;
 vpi_register_systf(&data);
}
void (*vlog_startup_routines[])(void)={startup,0};

cases.source:
`timescale 1ns/1ns
module top;
reg a=0;wire y;assign y=a;
initial begin #1;$display("before %b",y);$net_write(y,1);
#1;$display("deposited %b",y);a=1;#1;a=0;#1;$display("resolved %b",y);end
endmodule

`timescale 1ns/1ns
module top;
reg a=0;wire y;assign y=a;
initial begin #1;$display("before %b",y);$net_write(y,5);
a=1;#1;a=0;#1;$display("forced %b",y);$net_write(y,6);
#1;$display("released %b",y);end
endmodule

`timescale 1ns/1ns
module top;
reg a=0;wire y,z;assign y=a;tran link0(y,z);
initial begin #1;$display("before %b %b",y,z);$net_write(z,5);
a=1;#1;a=0;#1;$display("forced %b %b",y,z);$net_write(z,6);
#1;$display("released %b %b",y,z);end
endmodule
